package backup

import (
	"bufio"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/osshield/gopbs/scan"
	"golang.org/x/sys/unix"
)

// virtualFS are kernel filesystems with nothing to back up: /proc, /sys, /dev and
// friends. Their contents are generated by the kernel, can be enormous (/proc/kcore)
// or block on read. Skipped wherever they are mounted, also below a host root
// mounted into the agent's container.
var virtualFS = map[string]bool{
	"proc": true, "sysfs": true, "devtmpfs": true, "devpts": true, "cgroup": true, "cgroup2": true,
	"debugfs": true, "tracefs": true, "securityfs": true, "pstore": true, "bpf": true, "configfs": true,
	"fusectl": true, "mqueue": true, "hugetlbfs": true, "binfmt_misc": true, "efivarfs": true, "nsfs": true,
	"rpc_pipefs": true,
}

// mountTypes maps device numbers to filesystem types from a mountinfo stream
// (/proc/self/mountinfo: "id parent major:minor root mountpoint opts ... - fstype ...")
func mountTypes(r io.Reader) map[uint64]string {
	out := map[uint64]string{}
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 64<<10), 1<<20)
	for sc.Scan() {
		fields := strings.Fields(sc.Text())
		sep := -1
		for i, f := range fields {
			if f == "-" {
				sep = i
				break
			}
		}
		if len(fields) < 3 || sep < 0 || sep+1 >= len(fields) {
			continue
		}
		maj, min, ok := strings.Cut(fields[2], ":")
		if !ok {
			continue
		}
		a, err1 := strconv.ParseUint(maj, 10, 32)
		b, err2 := strconv.ParseUint(min, 10, 32)
		if err1 != nil || err2 != nil {
			continue
		}
		out[unix.Mkdev(uint32(a), uint32(b))] = fields[sep+1]
	}
	return out
}

// mountFilter builds the scan filter: virtual filesystems are always left out, and
// with oneFS so is every filesystem other than the one each root is on (a mount
// point below a root is omitted with its contents, like proxmox-backup-client
// without --all-file-systems). Each mount point left out is logged once.
func mountFilter(roots []string, oneFS bool) func(path, archivePath string, st scan.Stat) bool {
	types := map[uint64]string{}
	if f, err := os.Open("/proc/self/mountinfo"); err == nil {
		types = mountTypes(f)
		_ = f.Close()
	}
	return newMountFilter(roots, oneFS, types, func(p string) (uint64, bool) {
		var st unix.Stat_t
		if err := unix.Stat(p, &st); err != nil {
			return 0, false
		}
		return uint64(st.Dev), true
	})
}

func newMountFilter(roots []string, oneFS bool, types map[uint64]string, devOf func(string) (uint64, bool)) func(path, archivePath string, st scan.Stat) bool {
	type root struct {
		path string
		dev  uint64
	}
	var rs []root
	for _, r := range roots {
		if dev, ok := devOf(r); ok {
			rs = append(rs, root{filepath.Clean(r), dev})
		}
	}
	rootDev := func(p string) (uint64, bool) {
		best := -1
		for i, r := range rs {
			if (p == r.path || r.path == "/" || strings.HasPrefix(p, r.path+"/")) && (best < 0 || len(r.path) > len(rs[best].path)) {
				best = i
			}
		}
		if best < 0 {
			return 0, false
		}
		return rs[best].dev, true
	}
	return func(path, _ string, st scan.Stat) bool {
		if t := types[st.Dev]; virtualFS[t] {
			slog.Info("Leaving out a kernel filesystem", "path", path, "type", t)
			return false
		}
		if oneFS {
			if dev, ok := rootDev(path); ok && st.Dev != dev {
				slog.Info("Leaving out another filesystem (one_file_system)", "path", path, "type", types[st.Dev])
				return false
			}
		}
		return true
	}
}
